        return False
    return 1 <= n <= 1000

def ref(inp: str) -> str:
    n = json.loads(inp.strip())

    def can_partition(s: str, target: int) -> bool:
        def backtrack(idx: int, current_sum: int) -> bool:
            if idx == len(s):
                return current_sum == target
            if current_sum > target:
                return False
            for next_idx in range(idx + 1, len(s) + 1):
                val = int(s[idx:next_idx])
                if backtrack(next_idx, current_sum + val):
                    return True
            return False
        return backtrack(0, 0)

    ans = 0
    for i in range(1, n + 1):
        sq = i * i
        if can_partition(str(sq), i):
            ans += sq

    return json.dumps(ans)
