def _is_tree(edges, k):
    if not isinstance(edges, list) or len(edges) != k - 1:
        return False
    parent = list(range(k))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for e in edges:
        if not isinstance(e, list) or len(e) != 2:
