def _one_edit_or_equal(t, s):
    # Literal check: can T' (t) be obtained from candidate S (s) by one of the
    # four operations: equal, insert one char, delete one char, change one char.
    if t == s:
        return True
    lt, ls = len(t), len(s)
    # T' obtained by inserting one char into S
    if lt == ls + 1:
        for i in range(lt):
            if t[:i] + t[i + 1:] == s:
                return True
        return False
    # T' obtained by deleting one char from S
    if lt == ls - 1:
        for i in range(ls):
            if s[:i] + s[i + 1:] == t:
                return True
        return False
    # T' obtained by changing exactly one char of S
    if lt == ls:
        diff = sum(1 for a, b in zip(t, s) if a != b)
        return diff == 1
    return False


