        R = max(S, T)
        u_class = find(L - 1)
        for m in range(L, R - 1):
            v_class = find(m)
            if u_class == v_class:
                return False
            if S < T:
                adj[u_class].add(v_class)
            else:
                adj[v_class].add(u_class)

    in_degree = {u: 0 for u in nodes}
    for u in adj:
        for v in adj[u]:
            in_degree[v] += 1

    queue = [u for u in nodes if in_degree[u] == 0]
    visited = 0
    while queue:
        u = queue.pop()
        visited += 1
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    return visited == len(nodes)

