from hypothesis import strategies as st


def _ring_dist(N, a, b, blocked):
    # BFS on ring 1..N (adjacent i,i+1 and N,1), avoiding node `blocked`.
    # Returns the number of steps from a to b, or None if unreachable.
    if a == b:
        return 0
    seen = {a}
    frontier = [a]
    d = 0
    while frontier:
        d += 1
        nxt = []
        for u in frontier:
            for v in (u % N + 1, (u - 2) % N + 1):
                if v == blocked or v in seen:
                    continue
                if v == b:
                    return d
                seen.add(v)
                nxt.append(v)
        frontier = nxt
    return None


