from hypothesis import strategies as st


def _dist(N, p, q, T):
    """Minimum ops to move the hand at p (0-indexed) to T, other hand fixed at q.
    Only one of the two ring-arcs between p and T contains q; take the other."""
    d1 = (T - p) % N                      # clockwise steps p -> T
    if (q - p) % N < d1:                  # q lies strictly inside the clockwise arc
        return (p - T) % N                # ... so go the other way
    return d1


